import json
import random

# 雑学のカテゴリ
categories = {
    "科学": [
        "光", "音", "重力", "温度", "電気", "磁石", "水", "空気",
        "火", "氷", "時間", "原子", "分子", "エネルギー", "波"
    ],
    "宇宙": [
        "太陽", "月", "地球", "火星", "木星", "土星", "金星",
        "水星", "星", "銀河", "ブラックホール", "宇宙空間"
    ],
    "動物": [
        "猫", "犬", "イルカ", "クジラ", "ペンギン", "カラス",
        "タコ", "カメ", "ゾウ", "キリン", "ライオン", "チーター",
        "フクロウ", "コウモリ", "アリ", "ハチ"
    ],
    "人体": [
        "脳", "心臓", "血液", "筋肉", "骨", "皮膚", "目",
        "耳", "鼻", "舌", "髪", "睡眠", "体温"
    ],
    "食べ物": [
        "チョコレート", "コーヒー", "お米", "パン", "卵",
        "バナナ", "りんご", "トマト", "じゃがいも", "カレー",
        "寿司", "ラーメン", "牛乳", "蜂蜜"
    ],
    "身近なもの": [
        "スマートフォン", "テレビ", "冷蔵庫", "電子レンジ",
        "エレベーター", "信号機", "傘", "鉛筆", "消しゴム",
        "鏡", "時計", "財布", "鍵"
    ],
    "日本": [
        "東京", "富士山", "新幹線", "コンビニ", "温泉",
        "桜", "神社", "お寺", "和食", "日本語", "都道府県"
    ],
    "言葉": [
        "日本語", "漢字", "ことわざ", "四字熟語", "英語",
        "数字", "名前", "言葉の由来"
    ],
    "歴史": [
        "古代日本", "江戸時代", "明治時代", "戦国時代",
        "世界史", "発明", "文明", "昔の生活"
    ],
    "自然": [
        "海", "山", "川", "雨", "雪", "雷", "雲",
        "虹", "風", "植物", "森林", "火山"
    ]
}

angles = [
    "実は意外と知られていないこと",
    "なぜそうなるのか",
    "身近なのに不思議なこと",
    "意外な理由",
    "知らないと驚くこと",
    "昔から続いている秘密",
    "意外な共通点",
    "知っているようで知らないこと",
    "思わず誰かに話したくなること",
    "一度知ると気になること"
]

facts = []

# 2000個作成
for category, topics in categories.items():
    for topic in topics:
        for angle in angles:
            facts.append({
                "id": len(facts) + 1,
                "category": category,
                "topic": topic,
                "angle": angle,
                "fact": f"{topic}には、{angle}があります。"
            })

# 2000個を超えた場合は2000個にする
random.shuffle(facts)
facts = facts[:2000]

# IDを振り直す
for i, item in enumerate(facts, 1):
    item["id"] = i

with open("trivia.json", "w", encoding="utf-8") as f:
    json.dump(facts, f, ensure_ascii=False, indent=2)

print("===================================")
print("trivia.json 作成完了")
print("雑学データ数:", len(facts))
print("===================================")
